Your expense tracker is below. Add an expense with its amount, category and date, then switch months to see totals, a split by category and what is left of your budget. Entries are saved on this PC when your app allows it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8">
<style>
body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f7f9;color:#1c1e21;max-width:640px}
h1{font-size:20px;margin:0 0 12px}
.card{background:#fff;border-radius:12px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.1)}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{font-size:14px;padding:8px;border:1px solid #ccd0d5;border-radius:8px;flex:1;min-width:100px}
button{background:#0f6cbd;color:#fff;border:0;cursor:pointer;flex:none}
button.x{background:none;color:#a4262c;padding:4px 8px}
.big{font-size:26px;font-weight:600}
.muted{color:#65676b;font-size:13px}
.bar{height:8px;background:#e4e6eb;border-radius:4px;overflow:hidden;margin:3px 0 8px}
.bar i{display:block;height:100%;background:#0f6cbd}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.over{color:#a4262c}
</style></head><body>
<h1>Monthly expenses</h1>

<div class="card">
  <div class="row">
    <input id="m" type="month">
    <input id="b" type="number" min="0" placeholder="Monthly budget (₹)">
  </div>
  <div class="big" id="total">₹0</div>
  <div class="muted" id="left"></div>
</div>

<div class="card">
  <div class="row">
    <input id="d" placeholder="What did you spend on?">
    <input id="a" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="c">
      <option>Food</option><option>Transport</option><option>Bills</option>
      <option>Rent</option><option>Shopping</option><option>Health</option>
      <option>Fun</option><option>Other</option>
    </select>
    <input id="dt" type="date">
    <button id="add">Add</button>
  </div>
  <div class="muted" id="msg"></div>
</div>

<div class="card"><b>By category</b><div id="cats" style="margin-top:8px"></div></div>
<div class="card"><b>Entries</b><div id="list" style="margin-top:4px"></div></div>

<script>
var items=[],budget=0;
try{items=JSON.parse(localStorage.getItem('exp')||'[]');budget=+localStorage.getItem('bud')||0}catch(e){}
var $=function(i){return document.getElementById(i)};
var today=new Date().toISOString().slice(0,10);
$('dt').value=today;$('m').value=today.slice(0,7);
if(budget)$('b').value=budget;
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN')}
function save(){try{localStorage.setItem('exp',JSON.stringify(items));localStorage.setItem('bud',budget)}catch(e){}}
function render(){
  var m=$('m').value;
  var rows=items.filter(function(x){return x.date.slice(0,7)===m}).sort(function(p,q){return q.date<p.date?-1:1});
  var total=rows.reduce(function(s,x){return s+x.amt},0);
  $('total').textContent=inr(total);
  var left=$('left');left.className='muted';
  if(budget>0){
    var r=budget-total;
    left.textContent=r>=0?inr(r)+' left of '+inr(budget):inr(-r)+' over your budget of '+inr(budget);
    if(r<0)left.className='muted over';
  }else left.textContent='Set a budget to see what is left.';
  var by={};rows.forEach(function(x){by[x.cat]=(by[x.cat]||0)+x.amt});
  var cats=$('cats');cats.innerHTML='';
  var keys=Object.keys(by).sort(function(p,q){return by[q]-by[p]});
  if(!keys.length)cats.textContent='Nothing yet.';
  keys.forEach(function(k){
    var w=document.createElement('div');
    var t=document.createElement('div');t.className='row';t.style.margin=0;t.style.justifyContent='space-between';
    var a=document.createElement('span');a.textContent=k;
    var b=document.createElement('span');b.textContent=inr(by[k])+' ('+Math.round(by[k]/total*100)+'%)';
    t.appendChild(a);t.appendChild(b);
    var bar=document.createElement('div');bar.className='bar';
    var f=document.createElement('i');f.style.width=(by[k]/total*100)+'%';bar.appendChild(f);
    w.appendChild(t);w.appendChild(bar);cats.appendChild(w);
  });
  var list=$('list');list.innerHTML='';
  if(!rows.length)list.textContent='No entries for this month.';
  rows.forEach(function(x){
    var it=document.createElement('div');it.className='item';
    var l=document.createElement('div');
    l.textContent=x.desc;
    var s=document.createElement('div');s.className='muted';s.textContent=x.cat+' · '+x.date;
    l.appendChild(s);
    var r=document.createElement('div');
    var am=document.createElement('span');am.textContent=inr(x.amt);
    var del=document.createElement('button');del.className='x';del.textContent='Delete';
    del.onclick=function(){items.splice(items.indexOf(x),1);save();render()};
    r.appendChild(am);r.appendChild(del);
    it.appendChild(l);it.appendChild(r);list.appendChild(it);
  });
}
$('add').onclick=function(){
  var desc=$('d').value.trim(),amt=parseFloat($('a').value),dt=$('dt').value;
  if(!desc||!(amt>0)||!dt){$('msg').textContent='Add a name, an amount above 0 and a date.';return}
  $('msg').textContent='';
  items.push({desc:desc,amt:amt,cat:$('c').value,date:dt});
  $('d').value='';$('a').value='';
  $('m').value=dt.slice(0,7);
  save();render();
};
$('b').oninput=function(){budget=parseFloat($('b').value)||0;save();render()};
$('m').onchange=render;
render();
</script>
</body></html>
```
